// credential, request data or a stack trace (docs/SECURITY.md section 18).
func validateApiErrorMessage(value any, path string, out *[]SchemaViolation) {
	checkString(value, path, out, stringOpts{minLength: 1, maxLength: 1024, pattern: pattern9})
}

// validateAPIError checks a ApiError value.
func validateAPIError(value any, path string, out *[]SchemaViolation) {
	source, ok := checkObject(value, path, out, []string{"code", "message", "details"}, []string{"code", "message"})
	if !ok {
		return
	}
	if field, present := source["code"]; present {
		validateErrorClass(field, path+".code", out)
	}
	if field, present := source["message"]; present {
		validateApiErrorMessage(field, path+".message", out)
	}
	if field, present := source["details"]; present {
		validateAPIErrorDetails(field, path+".details", out)
	}
}

// validateAPIMeta checks a ApiMeta value.
func validateAPIMeta(value any, path string, out *[]SchemaViolation) {
	source, ok := checkObject(value, path, out, []string{"request_id", "next_cursor"}, []string{"request_id"})
	if !ok {
		return
	}
	if field, present := source["request_id"]; present {
		validateIdentifier(field, path+".request_id", out)
	}
	if field, present := source["next_cursor"]; present {
		validateCursor(field, path+".next_cursor", out)
	}
}

// validateAPIErrorResponse checks a ApiErrorResponse value.
func validateAPIErrorResponse(value any, path string, out *[]SchemaViolation) {
	source, ok := checkObject(value, path, out, []string{"error", "meta"}, []string{"error", "meta"})
	if !ok {
		return
	}
	if field, present := source["error"]; present {
		validateAPIError(field, path+".error", out)
	}
	if field, present := source["meta"]; present {
		validateAPIMeta(field, path+".meta", out)
	}
}

// validateCursorClaimsVersion checks cursor format version. A cursor of another
// version is refused rather than guessed at.
func validateCursorClaimsVersion(value any, path string, out *[]SchemaViolation) {
	checkInteger(value, path, out, 1, 1)
}

// validateCursorClaimsSortKey checks value of the collection's sort column at the last
// row of the previous page.
func validateCursorClaimsSortKey(value any, path string, out *[]SchemaViolation) {
	checkString(value, path, out, stringOpts{minLength: 1, maxLength: 128, pattern: pattern9})
}

// validateCursorClaims checks a CursorClaims value.
func validateCursorClaims(value any, path string, out *[]SchemaViolation) {
	source, ok := checkObject(value, path, out, []string{"version", "sort_key", "id"}, []string{"version", "sort_key", "id"})
	if !ok {
		return
	}
	if field, present := source["version"]; present {
		validateCursorClaimsVersion(field, path+".version", out)
	}
	if field, present := source["sort_key"]; present {
		validateCursorClaimsSortKey(field, path+".sort_key", out)
	}
	if field, present := source["id"]; present {
		validateIdentifier(field, path+".id", out)
	}
}
